const input = $input.first().json;
const body = input.body ?? input;

const required = ['fullName', 'email', 'academicId', 'otp'];
const missing = required.filter((key) => !body[key]);
if (missing.length) {
  throw new Error('Missing OTP fields: ' + missing.join(', '));
}

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;max-width:560px;margin:0 auto;background:#0f172a;color:#e2e8f0;border-radius:16px;overflow:hidden;">
  <div style="padding:24px;background:linear-gradient(135deg,#002b49,#0369a1);text-align:center;">
    <div style="color:#bae6fd;font-size:12px;letter-spacing:1px;text-transform:uppercase;">Galala University Transport</div>
    <h1 style="margin:8px 0 0;color:#ffffff;font-size:22px;">Your account verification code</h1>
  </div>
  <div style="padding:28px;">
    <p style="margin:0 0 16px;font-size:15px;">Hello <strong>${body.fullName}</strong>,</p>
    <p style="margin:0 0 20px;color:#cbd5e1;font-size:14px;line-height:1.6;">Use this one-time password to finish creating your Bus Aesh student account.</p>
    <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:20px;">
      <tr><td style="padding:6px 0;color:#94a3b8;">Name</td><td style="padding:6px 0;color:#ffffff;">${body.fullName}</td></tr>
      <tr><td style="padding:6px 0;color:#94a3b8;">Gmail / Outlook</td><td style="padding:6px 0;color:#ffffff;">${body.email}</td></tr>
      <tr><td style="padding:6px 0;color:#94a3b8;">Academic ID</td><td style="padding:6px 0;color:#ffffff;">${body.academicId}</td></tr>
    </table>
    <div style="background:#1e293b;border:2px dashed #38bdf8;border-radius:12px;padding:20px;text-align:center;">
      <div style="color:#94a3b8;font-size:11px;letter-spacing:1px;text-transform:uppercase;">OTP</div>
      <div style="font-family:Consolas,monospace;font-size:34px;font-weight:800;letter-spacing:8px;color:#38bdf8;margin-top:6px;">${body.otp}</div>
    </div>
    <p style="margin:18px 0 0;color:#f59e0b;font-size:13px;">This code expires in ${body.expiresInMinutes || 15} minutes.</p>
  </div>
</div>`;

return [{
  json: {
    fullName: body.fullName,
    email: body.email,
    academicId: String(body.academicId),
    otp: String(body.otp),
    subject: `Galala Bus verification code: ${body.otp}`,
    html,
  },
}];
